select jsonb_build_object('category', 'orphan_attachments', 'rows', (select coalesce(jsonb_agg(x),'[]') from (select id,owner_id,kind,target_id from meetany_private.attachments a where case kind when 'request' then not exists(select 1 from public.requests where id=a.target_id) when 'offer' then not exists(select 1 from public.offers where id=a.target_id) when 'conversation' then not exists(select 1 from meetany_private.conversations where id=a.target_id) when 'verification' then not exists(select 1 from public.profiles where id=a.target_id) when 'deal' then not exists(select 1 from meetany_private.deals where id=a.target_id) when 'issue' then not exists(select 1 from meetany_private.deal_issues where id=a.target_id) else false end) x));
